<script setup>
import { Link } from '@inertiajs/vue3';import{onMounted,onUnmounted,ref}from'vue';
const notices=ref([]);const receive=event=>{const id=Date.now()+Math.random();notices.value=[{id,...event.detail},...notices.value].slice(0,4);setTimeout(()=>notices.value=notices.value.filter(item=>item.id!==id),8000);};onMounted(()=>window.addEventListener('ppa:realtime',receive));onUnmounted(()=>window.removeEventListener('ppa:realtime',receive));
</script>
<template><div class="pointer-events-none fixed right-3 top-3 z-[80] flex w-[calc(100%-1.5rem)] max-w-sm flex-col gap-3 sm:right-5 sm:top-5"><TransitionGroup enter-active-class="transition duration-300" enter-from-class="translate-x-8 opacity-0" leave-active-class="transition duration-200" leave-to-class="translate-x-8 opacity-0"><article v-for="notice in notices" :key="notice.id" class="pointer-events-auto overflow-hidden rounded-2xl border border-red-100 bg-white shadow-[0_20px_60px_rgba(15,23,42,.2)]"><div class="h-1 bg-gradient-to-r from-red-700 via-red-500 to-red-300"></div><div class="flex items-start gap-3 p-4"><div class="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-red-50 text-red-700"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></div><div class="min-w-0 flex-1"><p class="text-[9px] font-black uppercase tracking-[.18em] text-red-600">Notifikasi Realtime</p><h3 class="mt-1 text-sm font-black text-slate-950">{{notice.title}}</h3><p class="mt-1 truncate text-xs text-slate-500">{{notice.message}}</p><Link :href="notice.href" class="mt-2 inline-block text-xs font-black text-red-600">Lihat data →</Link></div><button class="text-lg text-slate-400" @click="notices=notices.filter(item=>item.id!==notice.id)">×</button></div></article></TransitionGroup></div></template>
